cat > /workspace/internal/cmd/schema.go << 'EOF'
package cmd

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"

	"github.com/hashicorp/hcl/v2"
	"github.com/hashicorp/hcl/v2/hclwrite"
	"github.com/spf13/cobra"
)

var schemaCmd = &cobra.Command{
	Use:     "schema",
	Short:   "Work with atlas schemas.",
	Long:    "The `atlas schema` command groups subcommands working with declarative Atlas schemas.",
	Run: func(cmd *cobra.Command, args []string) {
		cmd.Help()
	},
}

func init() {
	schemaCmd.AddCommand(schemaFmtCmd)
	schemaCmd.AddCommand(schemaDiffCmd)
	schemaCmd.AddCommand(schemaApplyCmd)
	schemaCmd.AddCommand(schemaCleanCmd)
	schemaCmd.AddCommand(schemaInspectCmd)
}

var schemaFmtCmd = &cobra.Command{
	Use:   "fmt [path ...]",
	Short: "Formats Atlas HCL files",
	Long: `'atlas schema fmt' formats all ".hcl" files under the given paths using
canonical HCL layout style as defined by the github.com/hashicorp/hcl/v2/hclwrite package.
Unless stated otherwise, the fmt command will use the current directory.

After running, the command will print the names of the files it has formatted. If all
files in the directory are formatted, no input will be printed out.`,
	RunE: func(cmd *cobra.Command, args []string) error {
		// Default to current directory if no paths provided
		paths := args
		if len(paths) == 0 {
			paths = []string{"."}
		}

		var formatted []string

		for _, path := range paths {
			files, err := collectHCLFiles(path)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				return err
			}

			for _, file := range files {
				if err := formatHCLFile(file); err == nil {
					formatted = append(formatted, file)
				}
			}
		}

		// Sort and output formatted files
		sort.Strings(formatted)
		for _, f := range formatted {
			fmt.Println(f)
		}

		return nil
	},
}

var schemaDiffCmd = &cobra.Command{
	Use:   "diff",
	Short: "Calculate and print the diff between two schemas.",
	Long: `'atlas schema diff' reads the state of two given schema definitions, 
calculates the difference in their schemas, and prints a plan of
SQL statements to migrate the "from" database to the schema of the "to" database.
The database states can be read from a connected database, an HCL project or a migration directory.`,
	Run: func(cmd *cobra.Command, args []string) {
		fmt.Println("diff command not implemented")
	},
}

var schemaApplyCmd = &cobra.Command{
	Use:   "apply",
	Short: "Apply an atlas schema to a target database.",
	Run: func(cmd *cobra.Command, args []string) {
		fmt.Println("apply command not implemented")
	},
}

var schemaCleanCmd = &cobra.Command{
	Use:   "clean",
	Short: "Removes all objects from the connected database.",
	Run: func(cmd *cobra.Command, args []string) {
		fmt.Println("clean command not implemented")
	},
}

var schemaInspectCmd = &cobra.Command{
	Use:   "inspect",
	Short: "Inspect a database and print its schema in Atlas DDL syntax.",
	Run: func(cmd *cobra.Command, args []string) {
		fmt.Println("inspect command not implemented")
	},
}

func collectHCLFiles(path string) ([]string, error) {
	var files []string

	info, err := os.Stat(path)
	if err != nil {
		return nil, err
	}

	if !info.IsDir() {
		// Single file
		if filepath.Ext(path) == ".hcl" {
			files = append(files, path)
		}
		return files, nil
	}

	// Directory - walk and collect .hcl files
	entries, err := os.ReadDir(path)
	if err != nil {
		return nil, err
	}

	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		if filepath.Ext(entry.Name()) == ".hcl" {
			files = append(files, filepath.Join(path, entry.Name()))
		}
	}

	sort.Strings(files)
	return files, nil
}

func formatHCLFile(filename string) error {
	// Read the file
	content, err := os.ReadFile(filename)
	if err != nil {
		return err
	}

	// Parse the HCL
	file, diags := hclwrite.ParseHCL(content, filename)
	if diags.HasErrors() {
		// Even if there are errors, we still format what we can
		// The atlas tool seems to do this
	}

	// Format the file
	formatted := hclwrite.Format(file.Bytes())

	// Write back if changed
	err = os.WriteFile(filename, formatted, 0644)
	if err != nil {
		return err
	}

	return nil
}
EOF

